@Override protected Dialog onCreateDialog(int id){
  Dialog dialog=null;
switch (id) {
case DIALOG_LOGIN_PROGRESS:{
      ProgressDialog working_dialog=new ProgressDialog(this);
      working_dialog.setMessage(getResources().getString(R.string.auth_trying_to_login));
      working_dialog.setIndeterminate(true);
      working_dialog.setCancelable(true);
      working_dialog.setOnCancelListener(new DialogInterface.OnCancelListener(){
        @Override public void onCancel(        DialogInterface dialog){
          Log.i(TAG,"Login canceled");
          if (mAuthThread != null) {
            try {
              mAuthThread.interrupt();
            } catch (SecurityException e) {
              Log.e(TAG, "Security exception when interrupting auth thread", e);
            }
            finish();
          }
        }
      }
);
      dialog=working_dialog;
      break;
    }
default:  Log.e(TAG,"Incorrect dialog called with id = " + id);
}
return dialog;
}
